const profileById = new Map(profiles.map((profile) => [profile.id, profile]));

const sources: Source[] = recipes.map(({id, sourceTitle, url, author, book}) => ({
  id: `batch-f-${id}`,
  title: sourceTitle,
  url,
  author,
  book,
  checkedAt,
}));

const versions: RecipeVersion[] = recipes.map((recipe) => {
  const profile = profileById.get(recipe.id);
  if (!profile) throw new Error(`Missing Batch F profile: ${recipe.id}`);
  return {
    id: `${recipe.id}-batch-f`,
    cocktailId: recipe.id,
    label: sourceLabel(recipe.publisher),
    sourceId: `batch-f-${recipe.id}`,
    servings: recipe.servings ?? 1,
    ingredients: recipe.ingredients,
    steps: recipe.steps,
    originalLanguage: 'en',
    originalSteps: recipe.originalSteps,
    glass: recipe.glass,
    garnish: recipe.garnish,
    flavours: profile.flavours,
    tastes: profile.tastes,
    strength: profile.strength,
    approachability: profile.approachability,
    profileBasis: 'editorial',
    profileNote: editorial(profile),
    sourceChecked: true,
    translationStatus: 'draft',
  };
});

const cocktails: Cocktail[] = profiles.map((profile) => ({
  id: profile.id,
  name: profile.name,
  aliases: profile.aliases ?? [],
  category: 'classic',
  description: profile.description,
  versionIds: [`${profile.id}-batch-f`],
  defaultVersionId: `${profile.id}-batch-f`,
  accent: profile.accent,
}));

export const batchF: CatalogueBatch = {cocktails, versions, sources, ingredients, brands};

